       #define N 307
       #define INF 1000000
       typedef struct
       {
           int from;
           int to;
           char *fromCity;
           char *toCity;
           int value;
       } Data;
       int *getPath(int *path[], int i, int j)
       {
           int *ret = (int *)malloc(sizeof(int));
           for (int i = 0; i < 20; i++)
           {
                 ret[i] = -1;
           }
           if (i == j || path[i][j] == -1)
           {
                 return ret;
           }
           int temp = i;
           int k = 0;
           while (temp != j)
           {
                 ret[k++] = temp;
                 temp = path[temp][j];
           }
           ret[k++] = temp;
           return ret;
       }


